CREATE TABLE public.exit_checklist_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES public.plans(id), custom_plan_id uuid REFERENCES public.custom_plans(id), code text NOT NULL, stage text NOT NULL, item_text text NOT NULL, owner_side text NOT NULL DEFAULT 'Alcor', financial boolean NOT NULL DEFAULT false, anchor text NOT NULL DEFAULT 'exit', offset_days integer NOT NULL DEFAULT 0, working_days boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, source text NOT NULL DEFAULT 'Signed plan agreement', CHECK(owner_side IN ('Alcor','Hotel','Both')), CHECK(anchor IN ('notice','exit')), CHECK(offset_days BETWEEN -365 AND 365));
GRANT SELECT,INSERT,UPDATE ON public.exit_checklist_items TO authenticated; GRANT ALL ON public.exit_checklist_items TO service_role;
ALTER TABLE public.exit_checklist_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY exit_template_admin ON public.exit_checklist_items FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX exit_checklist_base_code ON public.exit_checklist_items(plan_id,code) WHERE custom_plan_id IS NULL;
CREATE UNIQUE INDEX exit_checklist_custom_code ON public.exit_checklist_items(custom_plan_id,code) WHERE custom_plan_id IS NOT NULL;
ALTER TABLE public.client_tasks ADD COLUMN exit_stage text, ADD COLUMN exit_owner_side text, ADD COLUMN exit_financial boolean NOT NULL DEFAULT false;
ALTER TABLE public.client_launches ADD COLUMN exit_checklist_version integer;
COMMENT ON TABLE public.offboarding_templates IS 'DEPRECATED for new exits: replaced by exit_checklist_items; preserve inactive rows and historic tasks.';
CREATE FUNCTION public.exit_working_after(_date date,_days integer) RETURNS date LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE d date:=_date; n integer:=0; BEGIN IF _days<0 OR _days>365 THEN RAISE EXCEPTION 'Invalid working-day offset'; END IF; WHILE n<_days LOOP d:=d+1; IF extract(isodow FROM d)<>7 AND NOT EXISTS(SELECT 1 FROM activity_holidays WHERE day=d) THEN n:=n+1; END IF; END LOOP; RETURN d; END $$;
CREATE FUNCTION public.exit_item_due(_notice date,_exit date,_anchor text,_offset integer,_working boolean) RETURNS date LANGUAGE sql STABLE SET search_path=public AS $$ SELECT CASE WHEN _working THEN exit_working_after(CASE WHEN _anchor='notice' THEN _notice ELSE _exit END,_offset) ELSE CASE WHEN _anchor='notice' THEN _notice ELSE _exit END+_offset END $$;
CREATE FUNCTION public.effective_exit_items(_launch uuid) RETURNS SETOF public.exit_checklist_items LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT e.* FROM client_launches l LEFT JOIN custom_plans c ON c.id=l.custom_plan_id LEFT JOIN plan_versions v ON v.id=c.base_plan_version_id JOIN exit_checklist_items e ON e.plan_id=coalesce(v.plan_id,l.plan_id) WHERE l.id=_launch AND e.active AND (CASE WHEN l.custom_plan_id IS NOT NULL AND EXISTS(SELECT 1 FROM exit_checklist_items x WHERE x.custom_plan_id=l.custom_plan_id) THEN e.custom_plan_id=l.custom_plan_id ELSE e.custom_plan_id IS NULL END) $$;
REVOKE ALL ON FUNCTION public.effective_exit_items(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.effective_exit_items(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.record_termination_notice(_launch_id uuid,_notice_date date,_notice_from text,_reason text DEFAULT NULL,_notice_file_path text DEFAULT NULL) RETURNS date LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l client_launches; p plans; d date; mt jsonb; n integer; BEGIN SELECT * INTO l FROM client_launches WHERE id=_launch_id FOR UPDATE; IF l.id IS NULL THEN RAISE EXCEPTION 'Launch not found'; END IF; IF NOT (can_edit_client(l.client_id) OR is_launch_am(l.id)) THEN RAISE EXCEPTION 'Only the Account Manager, BD or management can record a notice'; END IF; IF l.status NOT IN ('active','live') THEN RAISE EXCEPTION 'A notice can only be recorded on an active or live client'; END IF; IF _notice_date IS NULL OR _notice_from NOT IN ('client','alcor') THEN RAISE EXCEPTION 'Choose a notice date and party'; END IF; SELECT * INTO p FROM plans WHERE id=l.plan_id; d:=_notice_date+coalesce(l.notice_days,p.notice_days,CASE WHEN p.code='gmb_seo' THEN 90 ELSE 60 END); IF NOT EXISTS(SELECT 1 FROM effective_exit_items(l.id)) THEN RAISE EXCEPTION 'The plan exit checklist is missing; ask Admin to configure it'; END IF; mt:=_min_term_info(l.id,_notice_date); UPDATE client_launches SET status='offboarding',notice_within_min_term=coalesce((mt->>'within')::boolean,false),min_term_end=(mt->>'min_term_end')::date,notice_date=_notice_date,notice_from=_notice_from,notice_reason=_reason,notice_file_path=_notice_file_path,exit_date=d,exit_checklist_version=1 WHERE id=l.id;
INSERT INTO client_tasks(launch_id,client_id,module_code,code,name,standard,week_label,week_start,week_due,due_date,assignee_id,backup_id,sort_order,phase,exit_stage,exit_owner_side,exit_financial)
SELECT l.id,l.client_id,CASE WHEN e.financial THEN 'FIN' ELSE 'AM' END,'EXIT.'||e.code,e.item_text,e.source,e.stage,0,0,exit_item_due(_notice_date,d,e.anchor,e.offset_days,e.working_days),coalesce(a.primary_user_id,c.account_manager_id),a.backup_user_id,1000+e.sort_order,'offboarding',e.stage,e.owner_side,e.financial FROM effective_exit_items(l.id)e JOIN clients c ON c.id=l.client_id LEFT JOIN client_module_assignments a ON a.launch_id=l.id AND a.module_code=CASE WHEN e.financial THEN 'FIN' ELSE 'AM' END ON CONFLICT(launch_id,code) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; INSERT INTO launch_events(launch_id,user_id,kind,note) VALUES(l.id,auth.uid(),'termination_notice',n||' signed-plan exit items generated'); RETURN d; END $$;
CREATE FUNCTION public.exit_workspace(_launch uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid:=my_client_id(); fin boolean:=has_role(auth.uid(),'finance'); BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id,'launch_id',t.launch_id,'hotel_name',c.hotel_name,'code',t.code,'name',t.name,'stage',t.exit_stage,'owner_side',t.exit_owner_side,'due_date',t.due_date,'status',t.status,'evidence_url',t.evidence_url,'financial',t.exit_financial) ORDER BY t.sort_order) FROM client_tasks t JOIN client_launches l ON l.id=t.launch_id JOIN clients c ON c.id=t.client_id WHERE t.phase='offboarding' AND l.status='offboarding' AND (_launch IS NULL OR t.launch_id=_launch) AND ((owner=t.client_id AND t.exit_owner_side IN('Hotel','Both')) OR (owner IS NULL AND ((fin AND t.exit_financial) OR (NOT fin AND can_view_task(t.id)) OR is_manager(auth.uid()))))),'[]'); END $$;
CREATE FUNCTION public.update_exit_item(_task uuid,_status text,_evidence text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t client_tasks; owner uuid:=my_client_id(); BEGIN SELECT * INTO t FROM client_tasks WHERE id=_task FOR UPDATE; IF t.id IS NULL OR t.phase<>'offboarding' OR NOT EXISTS(SELECT 1 FROM client_launches WHERE id=t.launch_id AND status='offboarding') THEN RAISE EXCEPTION 'Exit item is not open'; END IF; IF NOT ((owner=t.client_id AND t.exit_owner_side IN('Hotel','Both')) OR (owner IS NULL AND (is_manager(auth.uid()) OR is_launch_am(t.launch_id) OR t.assignee_id=auth.uid() OR t.backup_id=auth.uid() OR (has_role(auth.uid(),'finance') AND t.exit_financial)))) THEN RAISE EXCEPTION 'This exit item is not assigned to you'; END IF; IF _status NOT IN('not_started','in_progress','done') THEN RAISE EXCEPTION 'Choose Not started, In progress or Done'; END IF; IF length(coalesce(_evidence,''))>2000 OR (coalesce(_evidence,'')<>'' AND _evidence !~ '^https://') THEN RAISE EXCEPTION 'Evidence must be an HTTPS link'; END IF; UPDATE client_tasks SET status=_status,evidence_url=nullif(_evidence,'') WHERE id=t.id; END $$;
CREATE FUNCTION public.exit_closure_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.status='offboarding' AND NEW.status='closed' AND (NOT EXISTS(SELECT 1 FROM client_tasks WHERE launch_id=OLD.id AND phase='offboarding') OR EXISTS(SELECT 1 FROM client_tasks WHERE launch_id=OLD.id AND phase='offboarding' AND status<>'done')) AND NOT (has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM admin_audit_log WHERE actor=auth.uid() AND action='offboarding_override' AND target_id=OLD.id::text AND details->>'transaction'=txid_current()::text)) THEN RAISE EXCEPTION 'All exit items must be Done before fully Offboarded'; END IF; RETURN NEW; END $$;
CREATE TRIGGER exit_closure_guard BEFORE UPDATE OF status ON public.client_launches FOR EACH ROW EXECUTE FUNCTION public.exit_closure_guard();
CREATE FUNCTION public._finish_plan_exit(_launch uuid,_override text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l client_launches; BEGIN SELECT * INTO l FROM client_launches WHERE id=_launch FOR UPDATE; IF l.id IS NULL OR l.status<>'offboarding' THEN RAISE EXCEPTION 'This client is not serving notice'; END IF; IF _override IS NOT NULL THEN IF NOT has_role(auth.uid(),'admin') OR length(trim(_override))<3 OR length(_override)>2000 THEN RAISE EXCEPTION 'Admin must provide an override reason'; END IF; INSERT INTO admin_audit_log(actor,action,target_type,target_id,outcome,details) VALUES(auth.uid(),'offboarding_override','client_launches',l.id::text,'ok',jsonb_build_object('reason',trim(_override),'transaction',txid_current()::text)); ELSE IF NOT (can_edit_client(l.client_id) OR is_launch_am(l.id)) THEN RAISE EXCEPTION 'Only the Account Manager, BD or management can close a client'; END IF; END IF; UPDATE client_launches SET status='closed',closed_at=now(),closed_reason='Terminated (notice from '||coalesce(l.notice_from,'—')||')' WHERE id=l.id; UPDATE client_pipelines SET status='ended' WHERE client_id=l.client_id; UPDATE clients SET status='inactive' WHERE id=l.client_id; INSERT INTO launch_events(launch_id,user_id,kind,note) VALUES(l.id,auth.uid(),'closed',CASE WHEN _override IS NULL THEN 'All exit items Done' ELSE 'Admin override: '||trim(_override) END); END $$;
REVOKE ALL ON FUNCTION public._finish_plan_exit(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public._finish_plan_exit(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.complete_offboarding(_launch_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT _finish_plan_exit(_launch_id,NULL) $$;
CREATE FUNCTION public.override_offboarding(_launch_id uuid,_reason text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT _finish_plan_exit(_launch_id,_reason) $$;
REVOKE ALL ON FUNCTION public.exit_workspace(uuid),public.update_exit_item(uuid,text,text),public.override_offboarding(uuid,text),public.exit_working_after(date,integer),public.exit_item_due(date,date,text,integer,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.exit_workspace(uuid),public.update_exit_item(uuid,text,text),public.override_offboarding(uuid,text),public.exit_working_after(date,integer),public.exit_item_due(date,date,text,integer,boolean) TO authenticated,service_role;
CREATE FUNCTION public.custom_exit_copy(_custom uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; BEGIN IF NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin only'; END IF; SELECT v.plan_id INTO pid FROM custom_plans c JOIN plan_versions v ON v.id=c.base_plan_version_id WHERE c.id=_custom; IF pid IS NULL THEN RAISE EXCEPTION 'Base plan not found'; END IF; INSERT INTO exit_checklist_items(plan_id,custom_plan_id,code,stage,item_text,owner_side,financial,anchor,offset_days,working_days,sort_order,source) SELECT plan_id,_custom,code,stage,item_text,owner_side,financial,anchor,offset_days,working_days,sort_order,source FROM exit_checklist_items WHERE plan_id=pid AND custom_plan_id IS NULL AND active ON CONFLICT(custom_plan_id,code) WHERE custom_plan_id IS NOT NULL DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.custom_exit_copy(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.custom_exit_copy(uuid) TO authenticated,service_role;